WITH sales_by_day AS ( SELECT cs.cs_sold_date_sk, DATE_PARSE(CAST(cs.cs_sold_date_sk AS VARCHAR), '%Y%m%d') AS sold_date, sm.sm_ship_mode_id, hd.hd_buy_potential, SUM(cs.cs_ext_sales_price) AS daily_sales, SUM(cs.cs_net_profit) AS daily_profit FROM catalog_sales cs JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk JOIN household_demographics hd ON cs.cs_bill_hdemo_sk = hd.hd_demo_sk GROUP BY cs.cs_sold_date_sk, sm.sm_ship_mode_id, hd.hd_buy_potential ) SELECT sold_date, sm_ship_mode_id, hd_buy_potential, daily_sales, daily_profit, LAG(daily_sales) OVER (PARTITION BY sm_ship_mode_id ORDER BY sold_date) AS prev_day_sales, (daily_sales - LAG(daily_sales) OVER (PARTITION BY sm_ship_mode_id ORDER BY sold_date)) / NULLIF(LAG(daily_sales) OVER (PARTITION BY sm_ship_mode_id ORDER BY sold_date), 0) * 100 AS pct_change_sales, CASE WHEN daily_sales > 0 AND (daily_sales - LAG(daily_sales) OVER (PARTITION BY sm_ship_mode_id ORDER BY sold_date)) > 0 THEN 'Increasing' WHEN daily_sales > 0 AND (daily_sales - LAG(daily_sales) OVER (PARTITION BY sm_ship_mode_id ORDER BY sold_date)) < 0 THEN 'Decreasing' ELSE 'Stable' END AS sales_trend FROM sales_by_day WHERE sold_date >= DATE '2023-01-01' ORDER BY sm_ship_mode_id, sold_date DESC LIMIT 100
